//! Start of exposure on `CLOCK_MONOTONIC`, rebuilt from UVC PTS/SCR.
//!
//! # What the camera tells us
//!
//! A frame's payload headers carry `PTS`: the device clock (`dwClockFrequency` Hz, 32 bits)
//! when capture of the frame began — the camera's start of exposure. Payloads also carry
//! `SCR`: a device-clock sample `STC` together with the 11-bit USB SOF counter read at the same
//! moment. SOF is the bus's 1 kHz frame number, generated by the *host controller*: it is a
//! clock both sides see. So SCR pairs ticks of the device clock with ticks of a host clock.
//!
//! # What Linux uvcvideo does (`hwtimestamps=1`, `uvc_video_clock_update`)
//!
//! For each payload with SCR it also records the host controller's own frame number
//! (`usb_get_current_frame_number`) and `ktime_get()` at URB completion: samples of
//! (device STC, device SOF, host SOF, host time). At each frame it takes the first and last of
//! the ~32 buffered samples and composes three two-point lines: PTS → device SOF (through
//! STC/SOF), device SOF → host SOF, host SOF → host time; SOF is carried in 1/65536 units to
//! keep sub-millisecond precision. The result is `buf.timestamp`, flagged
//! `V4L2_BUF_FLAG_TSTAMP_SRC_SOE`, which the laptop pod records as the exposure time.
//!
//! # When SOF is not the bus's
//!
//! The YUBI wrist camera's SCR carries the bus's SOF. A camera whose SOF is its own counter
//! (its SOF-to-host line off by more than 1 %, where crystals differ by tens of ppm) is not a
//! YUBI camera: the clock never locks on it, its frames stay untimed, and it never arms.
//!
//! # What this rig does, and why it differs
//!
//! usbfs exposes no "current frame number" to user space, so the host-SOF ↔ host-time pair
//! Linux reads at completion is not available. Instead each payload's host time is estimated
//! from the URB it arrived in: packet `k` of an `N`-packet isochronous URB reaped at host time
//! `R`, with service interval `Δ` (125 µs at high speed), was on the bus at about
//! `R − (N−1−k)·Δ`. That estimate is late by a non-negative, jittery completion latency
//! (interrupt moderation, scheduling) — never early. Likewise the device's STC is sampled
//! at or after the SOF edge it is paired with — never before. Both relations are therefore
//! *lower envelopes*:
//!
//! ```text
//!   host_est − 1 ms · sof  ≥  host_offset(t)          (bus time → CLOCK_MONOTONIC)
//!   stc − f · 1 ms · sof   ≥  device_offset(t)        (bus time → device ticks)
//! ```
//!
//! Per 100 ms of bus time the rig keeps the minimum of each residual, and fits a line
//! (offset + drift) through the minima of the last three complete seconds. Taking minima discards the
//! latency jitter that a first/last two-point line (Linux's construction) is exposed to; the
//! line tracks crystal drift between device, bus and `CLOCK_MONOTONIC` (tens of ppm, i.e. tens
//! of µs per second). A frame's start of exposure is then
//!
//! ```text
//!   bus  = (pts − a_dev) / (f + b_dev)        with stc ≈ a_dev + (f + b_dev) · bus
//!   soe  = bus + a_host + b_host · bus        on CLOCK_MONOTONIC, ns
//! ```
//!
//! with SOF unwrapped across its 2.048 s wrap by the host estimate, and STC/PTS unwrapped
//! across their 32-bit wrap by continuity (PTS precedes its own payloads' STC by far less than
//! 2³¹ ticks). Residual bias is the smallest completion latency plus the smallest
//! SOF-to-STC sampling delay the camera exhibits — tens of µs on a quiet bus in simulation. The
//! bound it is held to is 1 ms; it has not been measured against `uvcvideo` with an LED.

use std::collections::VecDeque;

/// Width of one minimum bucket, in bus time.
pub const BUCKET_NS: i64 = 100_000_000;
/// Buckets kept: the one filling and three seconds of complete ones the lines are fit over.
pub const WINDOW_BUCKETS: usize = 31;
/// Buckets needed before the clock is trusted.
pub const LOCK_BUCKETS: usize = 5;
const SOF_PERIOD_MS: i64 = 2048;
const NS_PER_MS: i64 = 1_000_000;

#[derive(Debug, Clone, Copy, PartialEq)]
struct Bucket {
    key: i64,
    /// Bus time (ns) of the sample that set the minimum.
    at: i64,
    /// The minimum residual.
    minimum: f64,
    /// The maximum residual: the spread is how noisy the relation is.
    maximum: f64,
}

/// Running per-bucket minima and a line through them.
#[derive(Debug, Default)]
struct Envelope {
    buckets: VecDeque<Bucket>,
}

impl Envelope {
    fn observe(&mut self, bus_ns: i64, residual: f64) {
        let key = bus_ns.div_euclid(BUCKET_NS);
        match self.buckets.back_mut() {
            Some(last) if last.key == key => {
                if residual < last.minimum {
                    last.minimum = residual;
                    last.at = bus_ns;
                }
                last.maximum = last.maximum.max(residual);
            }
            Some(last) if last.key > key => {
                // A sample from an older bucket (reordered): fold it into its bucket if kept.
                if let Some(bucket) = self.buckets.iter_mut().find(|b| b.key == key) {
                    if residual < bucket.minimum {
                        bucket.minimum = residual;
                        bucket.at = bus_ns;
                    }
                    bucket.maximum = bucket.maximum.max(residual);
                }
            }
            _ => {
                self.buckets.push_back(Bucket {
                    key,
                    at: bus_ns,
                    minimum: residual,
                    maximum: residual,
                });
                while self.buckets.len() > WINDOW_BUCKETS {
                    self.buckets.pop_front();
                }
            }
        }
    }

    /// The buckets whose 100 ms are over: the one still filling has a minimum of too few
    /// samples, biased high, and sits where a line has the most leverage.
    fn complete(&self) -> impl Iterator<Item = &Bucket> + Clone {
        self.buckets
            .iter()
            .take(self.buckets.len().saturating_sub(1))
    }

    /// Least-squares line through the complete buckets' minima:
    /// residual ≈ a + b·(bus − reference).
    fn line(&self, reference: i64) -> Option<(f64, f64)> {
        let count = self.complete().count();
        if count < LOCK_BUCKETS {
            return None;
        }
        let n = count as f64;
        let xs = self.complete().map(|b| (b.at - reference) as f64);
        let mean_x = xs.clone().sum::<f64>() / n;
        let mean_y = self.complete().map(|b| b.minimum).sum::<f64>() / n;
        let mut sxx = 0.0;
        let mut sxy = 0.0;
        for (x, b) in xs.zip(self.complete()) {
            sxx += (x - mean_x) * (x - mean_x);
            sxy += (x - mean_x) * (b.minimum - mean_y);
        }
        let slope = if sxx > 0.0 { sxy / sxx } else { 0.0 };
        Some((mean_y - slope * mean_x, slope))
    }

    /// The widest within-bucket spread in the window.
    fn spread(&self) -> f64 {
        self.complete()
            .map(|b| b.maximum - b.minimum)
            .fold(0.0, f64::max)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Serialize)]
pub struct Quality {
    pub locked: bool,
    pub samples: u64,
    /// Whether the camera's SOF runs with the bus (`None` until there are buckets to tell).
    pub sof_is_bus: Option<bool>,
    /// Worst within-100 ms spread of the host-latency residual, µs.
    pub host_latency_spread_us: f64,
    /// Worst within-100 ms spread of the device STC-after-SOF residual, µs.
    pub device_sampling_spread_us: Option<f64>,
    /// Device clock rate against the bus, ppm off nominal.
    pub device_drift_ppm: Option<f64>,
    /// Bus clock against CLOCK_MONOTONIC, ppm.
    pub bus_drift_ppm: Option<f64>,
}

/// The SOF-to-host line may be off by this much and still be the bus (crystals: tens of ppm).
const BUS_SLOPE_LIMIT: f64 = 0.01;

use serde::Serialize;

#[derive(Debug)]
pub struct Clock {
    frequency_hz: f64,
    sof_origin_ns: Option<i64>,
    last_stc: Option<(u32, i64)>,
    host: Envelope,
    device: Envelope,
    samples: u64,
}

impl Clock {
    pub fn new(frequency_hz: u32) -> Self {
        Self {
            frequency_hz: f64::from(frequency_hz),
            sof_origin_ns: None,
            last_stc: None,
            host: Envelope::default(),
            device: Envelope::default(),
            samples: 0,
        }
    }

    /// Ticks per bus nanosecond, nominally.
    fn ticks_per_ns(&self) -> f64 {
        self.frequency_hz / 1e9
    }

    fn unwrap_sof(&mut self, sof: u16, host_ns: i64) -> i64 {
        let origin = *self
            .sof_origin_ns
            .get_or_insert(host_ns - i64::from(sof) * NS_PER_MS);
        let elapsed_ms = (host_ns - origin) as f64 / NS_PER_MS as f64;
        let wraps = ((elapsed_ms - f64::from(sof)) / SOF_PERIOD_MS as f64).round() as i64;
        i64::from(sof) + wraps * SOF_PERIOD_MS
    }

    fn unwrap_stc(&mut self, stc: u32) -> i64 {
        let absolute = match self.last_stc {
            None => i64::from(stc),
            Some((raw, absolute)) => absolute + i64::from(stc.wrapping_sub(raw) as i32),
        };
        self.last_stc = Some((stc, absolute));
        absolute
    }

    /// One SCR, from a payload whose bus slot was at about `host_ns` on CLOCK_MONOTONIC.
    pub fn observe(&mut self, stc: u32, sof: u16, host_ns: i64) {
        let bus_ns = self.unwrap_sof(sof, host_ns) * NS_PER_MS;
        let stc = self.unwrap_stc(stc);
        self.host.observe(bus_ns, (host_ns - bus_ns) as f64);
        self.device
            .observe(bus_ns, stc as f64 - self.ticks_per_ns() * bus_ns as f64);
        self.samples += 1;
    }

    /// Whether the SOF field is the bus's 1 kHz frame counter: its line against host
    /// arrival drifts like a crystal. `None` until there are enough buckets to tell.
    pub fn sof_is_bus(&self) -> Option<bool> {
        let reference = self.reference().unwrap_or(0);
        self.host
            .line(reference)
            .map(|(_, slope)| slope.abs() < BUS_SLOPE_LIMIT)
    }

    fn reference(&self) -> Option<i64> {
        self.host.complete().last().map(|b| b.at)
    }

    /// CLOCK_MONOTONIC ns of a frame's PTS, once enough SCRs have been seen.
    pub fn soe_ns(&self, pts: u32) -> Option<i64> {
        let reference = self.reference()?;
        if self.sof_is_bus() != Some(true) {
            return None;
        }
        let (a_dev, b_dev) = self.device.line(reference)?;
        let (a_host, b_host) = self.host.line(reference)?;
        let (raw, stc) = self.last_stc?;
        let pts = stc - i64::from(raw.wrapping_sub(pts) as i32);
        // stc ≈ k·bus + a_dev + b_dev·(bus − ref), with k nominal ticks/ns.
        let k = self.ticks_per_ns();
        let bus = (pts as f64 - a_dev + b_dev * reference as f64) / (k + b_dev);
        let host = bus + a_host + b_host * (bus - reference as f64);
        Some(host.round() as i64)
    }

    pub fn quality(&self) -> Quality {
        let reference = self.reference().unwrap_or(0);
        let k = self.ticks_per_ns();
        let sof_is_bus = self.sof_is_bus();
        Quality {
            locked: sof_is_bus == Some(true)
                && self.host.line(reference).is_some()
                && self.device.line(reference).is_some(),
            samples: self.samples,
            sof_is_bus,
            host_latency_spread_us: self.host.spread() / 1e3,
            device_sampling_spread_us: (k > 0.0).then(|| self.device.spread() / k / 1e3),
            device_drift_ppm: if k > 0.0 {
                self.device.line(reference).map(|(_, b)| b / k * 1e6)
            } else {
                None
            },
            bus_drift_ppm: self.host.line(reference).map(|(_, b)| b * 1e6),
        }
    }
}

#[cfg(test)]
pub(crate) mod simulation {
    //! A synthetic camera on a synthetic bus (standing in for a recording of the wrist
    //! camera's SCR stream). Every quantity the estimator must not depend on is perturbed: the
    //! device crystal (+40 ppm), the bus against CLOCK_MONOTONIC (−25 ppm), STC sampled at
    //! a random point in its SOF frame, a random completion latency on every URB, and
    //! STC starting just below its 32-bit wrap.

    pub struct Bus {
        pub frequency_hz: u32,
        device_ppm: f64,
        bus_ppm: f64,
        host_origin_ns: f64,
        stc_origin: f64,
        seed: u64,
    }

    impl Bus {
        pub fn new(frequency_hz: u32) -> Self {
            Self {
                frequency_hz,
                device_ppm: 40.0,
                bus_ppm: -25.0,
                host_origin_ns: 5_000_000_000.0,
                stc_origin: f64::from(u32::MAX) - 2.0e8,
                seed: 0x9e37_79b9_7f4a_7c15,
            }
        }

        pub fn random(&mut self) -> f64 {
            // xorshift64*: deterministic across runs.
            self.seed ^= self.seed >> 12;
            self.seed ^= self.seed << 25;
            self.seed ^= self.seed >> 27;
            (self.seed.wrapping_mul(0x2545_f491_4f6c_dd1d) >> 11) as f64 / (1u64 << 53) as f64
        }

        /// CLOCK_MONOTONIC of bus time `t` (ns since the bus origin).
        pub fn host_ns(&self, t: f64) -> f64 {
            self.host_origin_ns + t * (1.0 + self.bus_ppm * 1e-6)
        }

        /// The device clock at bus time `t`, unwrapped.
        pub fn ticks(&self, t: f64) -> f64 {
            self.stc_origin
                + t * 1e-9 * f64::from(self.frequency_hz) * (1.0 + self.device_ppm * 1e-6)
        }

        /// The SCR a payload built at bus time `t` would carry: STC sampled up to 1 ms after
        /// the SOF edge it pairs with.
        pub fn scr(&mut self, t: f64) -> (u32, u16) {
            let frame_ms = (t / 1e6).floor();
            let sampled = frame_ms * 1e6 + self.random() * 0.9e6;
            let stc = (self.ticks(sampled).round() as u64 & 0xffff_ffff) as u32;
            (stc, (frame_ms as u64 % 2048) as u16)
        }

        pub fn pts(&self, t: f64) -> u32 {
            (self.ticks(t).round() as u64 & 0xffff_ffff) as u32
        }

        /// A completion latency: 30 µs floor, exponential tail with a 400 µs mean, and an
        /// occasional 3 ms scheduling stall.
        pub fn latency_ns(&mut self) -> f64 {
            let tail = -400_000.0 * (1.0 - self.random()).ln();
            let stall = if self.random() < 0.01 {
                3_000_000.0
            } else {
                0.0
            };
            30_000.0 + tail + stall
        }
    }
}

#[cfg(test)]
mod tests {
    use super::simulation::Bus;
    use super::*;

    /// URBs of 32 packets at 125 µs carry SCRs; frames start exposure at 120.1 Hz. After the
    /// clock locks, every reconstructed start of exposure is within 100 µs of the truth,
    /// across SOF wraps (every 2.048 s) and the STC/PTS 32-bit wrap (at ~4.2 s here).
    #[test]
    fn reconstructs_start_of_exposure_through_drift_jitter_and_wraps() {
        for frequency in [48_000_000_u32, 15_000_000] {
            let mut bus = Bus::new(frequency);
            let mut clock = Clock::new(frequency);
            let packets = 32;
            let interval = 125_000.0;
            let frame_period = 1e9 * 513.0 / 61_612.0;
            let mut next_frame = 0.0;
            let mut worst: f64 = 0.0;
            let mut checked = 0;
            let mut urb_start = 0.0;
            while urb_start < 12e9 {
                let latency = bus.latency_ns();
                let reap = bus.host_ns(urb_start + (packets - 1) as f64 * interval) + latency;
                for k in 0..packets {
                    let slot = urb_start + k as f64 * interval;
                    let (stc, sof) = bus.scr(slot);
                    let estimate = reap - (packets - 1 - k) as f64 * interval;
                    clock.observe(stc, sof, estimate.round() as i64);
                }
                urb_start += packets as f64 * interval;
                // Frames whose exposure began more than 5 ms before now are closed now.
                while next_frame + 5e6 < urb_start {
                    if let Some(soe) = clock.soe_ns(bus.pts(next_frame)) {
                        let error = (soe as f64 - bus.host_ns(next_frame)).abs();
                        if next_frame > 1e9 {
                            worst = worst.max(error);
                            checked += 1;
                        }
                    }
                    next_frame += frame_period;
                }
            }
            assert!(checked > 1_000, "{checked}");
            assert!(worst < 100_000.0, "{frequency} Hz: worst error {worst} ns");
            let quality = clock.quality();
            assert!(quality.locked);
            assert_eq!(quality.sof_is_bus, Some(true));
            assert!(
                (quality.device_drift_ppm.unwrap() - 40.0).abs() < 2.0,
                "{quality:?}"
            );
        }
    }

    /// A camera whose SOF field is its own counter (STC / 12000 at 15 MHz: 1.25 kHz,
    /// wrapping every 1.64 s) is not on the bus: the clock never locks and no frame is timed.
    #[test]
    fn a_camera_counting_its_own_sof_never_locks() {
        let mut clock = Clock::new(15_000_000);
        for n in 0..30_000_i64 {
            let host = 1_000_000_000 + n * 125_000;
            let stc = (n * 125_000 * 15 / 1_000) as u32;
            let sof = ((i64::from(stc) / 12_000) % 2048) as u16;
            clock.observe(stc, sof, host);
        }
        let quality = clock.quality();
        assert_eq!(quality.sof_is_bus, Some(false), "{quality:?}");
        assert!(!quality.locked);
        assert_eq!(clock.soe_ns(1_000), None);
    }

    #[test]
    fn no_timestamp_before_half_a_second_of_scr() {
        let mut bus = Bus::new(48_000_000);
        let mut clock = Clock::new(48_000_000);
        let mut t = 0.0;
        while t < 0.3e9 {
            let (stc, sof) = bus.scr(t);
            clock.observe(stc, sof, bus.host_ns(t) as i64);
            t += 1e6;
        }
        assert_eq!(clock.soe_ns(bus.pts(0.2e9)), None);
        assert!(!clock.quality().locked);
    }
}
